// ------------------------------------------------------------------ region helpers

export function polygonArea(pts) {
  let a = 0;
  for (let i = 0, n = pts.length; i < n; i++) {
    const p = pts[i], q = pts[(i + 1) % n];
    a += p[0] * q[1] - q[0] * p[1];
  }
  return a / 2;
}

const orient = (pts, ccw) => ((polygonArea(pts) > 0) === ccw ? pts : pts.slice().reverse());

function unflat(f, k = 1, dx = 0, dy = 0) {
  const out = [];
  for (let i = 0; i < f.length; i += 2) out.push([f[i] * k + dx, f[i + 1] * k + dy]);
  return out;
}

// raw = [outerFlat, holeFlat, …] → region (scaled by k, shifted)
function regionFrom(raw, k, dx = 0, dy = 0) {
  return {
    outer: orient(unflat(raw[0], k, dx, dy), true),
    holes: raw.slice(1).map((h) => orient(unflat(h, k, dx, dy), false)),
  };
}

// Apply a point map to every vertex; windings are re-normalised (outer CCW, holes CW), so
// mirror maps (back-view text) work.
export function mapRegions(regions, fn) {
  return regions.map((r) => ({
    outer: orient(r.outer.map(([x, y]) => fn(x, y)), true),
    holes: r.holes.map((h) => orient(h.map(([x, y]) => fn(x, y)), false)),
  }));
}

export function regionBounds(regions) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const r of regions) for (const [x, y] of r.outer) {
    if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y;
  }
  return { x0, y0, x1, y1, w: x1 - x0, h: y1 - y0 };
}

export function regionsToOps(regions) {
  return regions.map((r) => ({ fill: r.outer, holes: r.holes }));
}

// Draw ops on a CanvasRenderingContext2D whose transform maps local mm → px. Accepts the
// nomos-glyphs ops ({ fill } / { stroke, closed, join, width }) plus { fill, holes }.
export function runOps(g, ops) {
  for (const op of ops) {
    g.beginPath();
    const pts = op.fill || op.stroke;
    g.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i][0], pts[i][1]);
    if (op.fill) {
      g.closePath();
      if (op.holes) {
        for (const h of op.holes) {
          g.moveTo(h[0][0], h[0][1]);
          for (let i = 1; i < h.length; i++) g.lineTo(h[i][0], h[i][1]);
          g.closePath();
        }
      }
      g.fill('evenodd');
      continue;
    }
    if (op.closed) g.closePath();
    g.lineWidth = op.width;
    g.lineJoin = op.join || 'round';
    g.stroke();
  }
}

export function drawRegions(g, regions) {
  runOps(g, regionsToOps(regions));
}

export function regionsToShapes(THREE, regions) {
  return regions.map((r) => {
    const s = new THREE.Shape(r.outer.map(([x, y]) => new THREE.Vector2(x, y)));
    for (const h of r.holes) s.holes.push(new THREE.Path(h.map(([x, y]) => new THREE.Vector2(x, y))));
    return s;
  });
}

// ------------------------------------------------------------------ meshing helpers
// For relief and domed parts built from regions (lume caps, rose relief, engraving floors).

// Distance from (x, y) to the nearest edge of a closed polygon.
export function distToPolygon(pts, x, y) {
  let best = Infinity;
  for (let i = 0, n = pts.length; i < n; i++) {
    const [ax, ay] = pts[i], [bx, by] = pts[(i + 1) % n];
    const ex = bx - ax, ey = by - ay;
    const l2 = ex * ex + ey * ey || 1e-12;
    const t = Math.max(0, Math.min(1, ((x - ax) * ex + (y - ay) * ey) / l2));
    const dx = ax + ex * t - x, dy = ay + ey * t - y;
    const d = dx * dx + dy * dy;
    if (d < best) best = d;
  }
  return Math.sqrt(best);
}

export function pointInPolygon(pts, x, y) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const [xi, yi] = pts[i], [xj, yj] = pts[j];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

// Split polygon edges longer than `step` so long straight sides get vertices.
export function resamplePolygon(pts, step) {
  const out = [];
  for (let i = 0, n = pts.length; i < n; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    const k = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / step));
    for (let j = 0; j < k; j++) out.push([a[0] + ((b[0] - a[0]) * j) / k, a[1] + ((b[1] - a[1]) * j) / k]);
  }
  return out;
}

// Mesh a STAR-SHAPED region (every boundary point visible from `centre`: circles, bars,
// triangles, hand lume windows, diamonds) as homothetic rings round the centre, so it can be
// displaced (domed lume caps, relief on curved faces) without cracks. The boundary is
// resampled every `step` mm; `rings` interior rings. Returns { xy: [[x, y], …],
// index: [i, j, k, …] (CCW), dist: [distance of each vertex to the boundary], ring: [0…rings] }.
export function meshStarRegion(outer, centre, { rings = 8, step = 0.05 } = {}) {
  const ccw = polygonArea(outer) > 0 ? outer : outer.slice().reverse();
  const B = resamplePolygon(ccw, step);
  const n = B.length;
  const xy = [[centre[0], centre[1]]];
  const ring = [0];
  for (let k = 1; k <= rings; k++) {
    // rings bunch towards the edge (where a dome curves most)
    const f = 1 - Math.pow(1 - k / rings, 1.6);
    for (const [x, y] of B) { xy.push([centre[0] + (x - centre[0]) * f, centre[1] + (y - centre[1]) * f]); ring.push(k); }
  }
  const index = [];
  const at = (k, i) => 1 + (k - 1) * n + (((i % n) + n) % n);
  for (let i = 0; i < n; i++) index.push(0, at(1, i), at(1, i + 1));
  for (let k = 1; k < rings; k++) {
    for (let i = 0; i < n; i++) {
      const a = at(k, i), b = at(k, i + 1), c = at(k + 1, i), d = at(k + 1, i + 1);
      index.push(a, c, d, a, d, b);
    }
  }
  const dist = xy.map(([x, y]) => distToPolygon(ccw, x, y));
  return { xy, index, dist, ring, boundaryStart: at(rings, 0), boundaryCount: n };
}

// ------------------------------------------------------------------ traced glyphs

export const SHIELD_SIZE = { w: SHIELD_W, h: SHIELD_H };
export { TUDOR_CAP, GENEVE_CAP };

// Where the traced prints sit on THIS dial (dial mm, +y = 12 o'clock): shield centre and
// height, wordmark / city baseline point (x centre, baseline y) and cap height.
export const DIAL_PRINT = {
  shield: { centre: SHIELD_DIAL_CENTRE, height: SHIELD_H },
  tudor: { base: TUDOR_DIAL_BASE, cap: TUDOR_CAP },
  geneve: { base: GENEVE_DIAL_BASE, cap: GENEVE_CAP },
};

// The shield centred on its bounding box at (cx, cy), `height` tall (native 1.696 on the
// dial). outlineOnly → just the silhouette (e.g. a raised clasp tab or a small engraved ⛉).
export function shieldRegions(height = SHIELD_H, { cx = 0, cy = 0, outlineOnly = false } = {}) {
  const k = height / SHIELD_H;
  const raw = outlineOnly ? [SHIELD_RAW[0]] : SHIELD_RAW;
  return [regionFrom(raw, k, cx, cy)];
}

const TUDOR_ORDER = ['T', 'U', 'D', 'O', 'R'];

// The wordmark with its baseline on y = 0, centred on x = 0, scaled to `capHeight`
// (flat tops of T/U/D/R; the O overshoots a little, as printed).
export function tudorRegions(capHeight = TUDOR_CAP) {
  const k = capHeight / TUDOR_CAP;
  return TUDOR_ORDER.map((ch) => regionFrom(TUDOR_RAW[ch], k));
}

// Letter by letter: [{ ch, x0, x1, xc, regions }] with x positions relative to the word
// centre (same scale), for laying the word round an arc (rotor, case back, bridges).
// Each letter's regions are re-centred on its own x centre (baseline stays y = 0).
export function tudorLetterRegions(capHeight = TUDOR_CAP) {
  const k = capHeight / TUDOR_CAP;
  return TUDOR_ORDER.map((ch) => {
    const reg = regionFrom(TUDOR_RAW[ch], k);
    const b = regionBounds([reg]);
    const xc = (b.x0 + b.x1) / 2;
    return { ch, x0: b.x0, x1: b.x1, xc, regions: mapRegions([reg], (x, y) => [x - xc, y]) };
  });
}

// GENEVE under the wordmark: baseline y = 0, centred, scaled to `capHeight`.
export function genevaRegions(capHeight = GENEVE_CAP) {
  const k = capHeight / GENEVE_CAP;
  return GENEVE_RAW.map((raw) => regionFrom(raw, k));
}

// The lower dial prints exactly where they sit on this dial (dial mm): 'depth' (200m:660ft),
// 'chrono1' (CHRONOMETER), 'chrono2' (OFFICIALLY CERTIFIED). Traced from the official macro.
export function dialTextRegions(id) {
  const raw = DIAL_TEXT_RAW[id];
  return raw ? raw.map((g) => regionFrom(g, 1)) : [];
}

// ------------------------------------------------------------------ the Tudor rose
// Proportions in units of the barb-tip radius (= the rose's radius), measured on the
// rectified crown macros. Sepal (barb) k points at angle 90° + 72°·k (+ rotation) — i.e. one
// barb straight up at rotation 0; the outer petals and the inner rose's points lie between.
export const ROSE = {
  barbTip: 1.0, barbBase: 0.74, barbHalfWidth: 0.075, // thorn from the petal junction out to the tip
  petalOuter: 0.89, petalInner: 0.645, rim: 0.07, // petal: scalloped outer edge, inner arc; raised rim round a slot
  starTip: 0.585, starWaist: 0.43, starTipRound: 0.025, // inner rose: five points at the outer petals' centres
  groove: 0.37, disc: 0.33, seed: 0.09, // groove round the raised centre disc; small domed seed
  relief: { rim: 1, barb: 1, star: 1, disc: 1, seed: 1.35 }, // suggested relative heights
};

function circleThrough(rj, half, rm) {
  // circle on the +x axis through (rm, 0) and (rj cos half, ±rj sin half): centre d, radius rho
  const d = (rm * rm - rj * rj) / (2 * (rm - rj * Math.cos(half)));
  return { d, rho: Math.abs(rm - d) };
}

function circleIntersectUpper(c1, c2) {
  // both centred on the x axis (at c.d); the intersection with y > 0
  const x = (c1.rho * c1.rho - c2.rho * c2.rho - c1.d * c1.d + c2.d * c2.d) / (2 * (c2.d - c1.d));
  const y2 = c1.rho * c1.rho - (x - c1.d) * (x - c1.d);
  return [x, Math.sqrt(Math.max(0, y2))];
}

// arc of circle c (centre (c.d, 0)) from point a to point b (both on it) through the circle's
// outermost point (angle 0 about its centre); n segments, the end point excluded
function arcBetween(c, a, b, n) {
  const a0 = Math.atan2(a[1], a[0] - c.d);
  const a1 = Math.atan2(b[1], b[0] - c.d);
  const out = [];
  for (let i = 0; i < n; i++) {
    const t = a0 + ((a1 - a0) * i) / n;
    out.push([c.d + c.rho * Math.cos(t), c.rho * Math.sin(t)]);
  }
  return out;
}

const rotPts = (pts, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return pts.map(([x, y]) => [x * c - y * s, x * s + y * c]);
};

function circlePts(r, n, cx = 0, cy = 0, ccw = true) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const t = ((ccw ? 1 : -1) * i * TAU) / n;
    out.push([cx + r * Math.cos(t), cy + r * Math.sin(t)]);
  }
  return out;
}

// The rose of `radius` (barb tips) centred at the origin. Returns regions grouped by relief
// level: { rims (5 petal rims, each with its slot), barbs (5), star (inner rose with the
// groove round the disc as its hole), disc, seed, ring (optional thin ring at `ring` radius),
// all }. `segments` scales the arc resolution (≥ 0.5 for small, distant crowns).
export function roseRegions(radius = 1, { rotation = 0, ring = 0, ringWidth = 0.05, segments = 1 } = {}) {
  const P = ROSE, R = radius;
  const nArc = Math.max(6, Math.round(18 * segments));
  const half = (36 * Math.PI) / 180;
  const rims = [], barbs = [];
  // Petal k in its own frame (axis = +x): the outer edge is a scallop (circle c1 through the
  // two junctions J± at barbBase, ±36°, bulging to petalOuter on the axis), the inner edge an
  // arc about the rose centre at petalInner, the ends radial (shared with the neighbours, so
  // the rims of two petals merge into one spoke under each barb). The raised rim runs round
  // that outline; the slot inside it is the outline offset inwards by the rim width.
  const c1 = circleThrough(P.barbBase, half, P.petalOuter);
  const J = [P.barbBase * Math.cos(half), P.barbBase * Math.sin(half)];
  const Jm = [J[0], -J[1]];
  const ri = P.petalInner, w = P.rim;
  const innerArc = (r, a0, a1, n) => {
    const out = [];
    for (let i = 0; i <= n; i++) { const t = a0 + ((a1 - a0) * i) / n; out.push([r * Math.cos(t), r * Math.sin(t)]); }
    return out;
  };
  const outerLoop = [
    ...arcBetween(c1, J, Jm, nArc * 2), // J+ → over the scallop → J− (end point excluded)
    Jm,
    ...innerArc(ri, -half, half, nArc), // (ri, −36°) → (ri, +36°)
  ];
  // slot: bounded by the end lines (the ±36° rays moved inwards by w), c1 shrunk by w and
  // the inner arc pushed out by w
  const u = [Math.cos(half), Math.sin(half)], nrm = [Math.sin(half), -Math.cos(half)];
  const onLine = (t, sy) => [t * u[0] + w * nrm[0], sy * (t * u[1] + w * nrm[1])];
  const tCircle = Math.sqrt((ri + w) ** 2 - w * w);
  // end line ∩ shrunk scallop: |t·u + w·n − (d,0)| = rho − w
  const c1s = { d: c1.d, rho: c1.rho - w };
  const ox = w * nrm[0] - c1s.d, oy = w * nrm[1];
  const B = 2 * (u[0] * ox + u[1] * oy), C = ox * ox + oy * oy - c1s.rho * c1s.rho;
  const tScal = (-B + Math.sqrt(Math.max(0, B * B - 4 * C))) / 2;
  const Kp = onLine(tScal, 1), Km = onLine(tScal, -1);
  const aIn = Math.atan2(onLine(tCircle, 1)[1], onLine(tCircle, 1)[0]);
  const slot = [
    onLine(tCircle, 1), Kp,
    ...arcBetween(c1s, Kp, Km, nArc * 2).slice(1),
    Km, onLine(tCircle, -1),
    ...innerArc(ri + w, -aIn, aIn, nArc).slice(1, -1),
  ];
  // barb in its own frame (axis = +x): concave flanks from the base half-width to the tip
  const barb = [];
  {
    const n = Math.max(4, Math.round(8 * segments));
    const b0 = P.barbBase - 0.04, w = P.barbHalfWidth;
    const right = [], left = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const x = b0 + (P.barbTip - b0) * t;
      const y = w * Math.pow(1 - t, 1.8); // concave thorn flank
      right.push([x, -y]);
      left.push([x, y]);
    }
    barb.push(...right, ...left.reverse().slice(1));
  }
  for (let k = 0; k < 5; k++) {
    const aBarb = rotation + Math.PI / 2 + (k * TAU) / 5;
    const aPetal = aBarb + half;
    rims.push({
      outer: orient(rotPts(outerLoop, aPetal).map(([x, y]) => [x * R, y * R]), true),
      holes: [orient(rotPts(slot, aPetal).map(([x, y]) => [x * R, y * R]), false)],
    });
    barbs.push({ outer: orient(rotPts(barb, aBarb).map(([x, y]) => [x * R, y * R]), true), holes: [] });
  }
  // inner rose: five points (slightly rounded) at the petal centres, concave sides
  const star = [];
  {
    const n = Math.max(6, Math.round(12 * segments));
    const tip = P.starTip, rc = 2 * P.starWaist - tip * Math.cos(half); // quad control radius on the barb axis
    for (let k = 0; k < 5; k++) {
      const aT0 = rotation + Math.PI / 2 + half + (k * TAU) / 5; // point k (petal centre)
      const aT1 = aT0 + (TAU / 5);
      const aB = aT0 + half; // barb axis between the two points
      const p0 = [tip * Math.cos(aT0), tip * Math.sin(aT0)];
      const p2 = [tip * Math.cos(aT1), tip * Math.sin(aT1)];
      const pc = [rc * Math.cos(aB), rc * Math.sin(aB)];
      // soften the point: start a little way down the edge, with a tiny arc round the tip
      const tr = P.starTipRound;
      for (let i = 0; i < n; i++) {
        const t = i / n, u = 1 - t;
        let x = u * u * p0[0] + 2 * u * t * pc[0] + t * t * p2[0];
        let y = u * u * p0[1] + 2 * u * t * pc[1] + t * t * p2[1];
        if (i === 0) { // pull the very tip in by tr (a tiny bevel instead of a needle)
          x *= 1 - tr / tip; y *= 1 - tr / tip;
        }
        star.push([x * R, y * R]);
      }
    }
  }
  const nC = Math.max(24, Math.round(64 * segments));
  const starRegion = { outer: orient(star, true), holes: [circlePts(P.groove * R, nC, 0, 0, false)] };
  const disc = { outer: circlePts(P.disc * R, nC), holes: [] };
  const seed = { outer: circlePts(P.seed * R, Math.max(16, Math.round(32 * segments))), holes: [] };
  const ringRegions = ring > 0 ? [{
    outer: circlePts(ring + ringWidth / 2, Math.max(48, Math.round(128 * segments))),
    holes: [circlePts(ring - ringWidth / 2, Math.max(48, Math.round(128 * segments)), 0, 0, false)],
  }] : [];
  return {
    rims, barbs, star: [starRegion], disc: [disc], seed: [seed], ring: ringRegions,
    all: [...rims, ...barbs, starRegion, disc, seed, ...ringRegions],
  };
}
